#!/bin/sh
# Self-test for scripts/coverage-gate.sh. It runs the gate's --check-only mode, which validates the exclusions and the
# package list without running any test, against small fixture modules. Each case names the status and the message the
# gate must give. No test of the real module runs here.
set -eu

here=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
gate="$here/coverage-gate.sh"
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
cases=0
failed=0

# make_fixture makes the module $work/$1 in the variable dir. It has a generated file with its header, a package with a
# test file, a command package with a test file, and the tests/support directory.
make_fixture() {
	dir="$work/$1"
	mkdir -p "$dir/internal/adapters/graphql" "$dir/internal/core/domain" "$dir/cmd/tool" "$dir/tests/support/stub" "$dir/scripts"
	printf 'module example.test/fixture\n' >"$dir/go.mod"
	printf '// Code generated by a fixture generator, DO NOT EDIT.\n\npackage graphql\n' >"$dir/internal/adapters/graphql/generated.go"
	printf 'package graphql\n' >"$dir/internal/adapters/graphql/graphql_test.go"
	printf 'package domain\n\nfunc Domain() int { return 1 }\n' >"$dir/internal/core/domain/domain.go"
	printf 'package domain\n' >"$dir/internal/core/domain/domain_test.go"
	printf 'package main\n\nfunc main() {}\n' >"$dir/cmd/tool/main.go"
	printf 'package main\n' >"$dir/cmd/tool/tool_test.go"
	printf 'package stub\n' >"$dir/tests/support/stub/stub.go"
}

# check runs the gate on the fixture root and compares its status and output with the expected ones. An optional fifth
# argument replaces the root's exclusion file with that content; \t and \n in it are tabs and newlines.
check() {
	name=$1
	want=$2
	text=$3
	root=$4
	if [ "$#" -ge 5 ]; then
		printf '%b' "$5" >"$root/scripts/coverage-exclusions.tsv"
	fi
	cases=$((cases + 1))
	got=0
	COVERAGE_ROOT="$root" sh "$gate" --check-only >"$work/out" 2>&1 || got=$?
	if [ "$got" -ne "$want" ] || ! grep -F -q -- "$text" "$work/out"; then
		failed=$((failed + 1))
		echo "FAIL $name: want status $want with '$text', got status $got:" >&2
		sed 's/^/  /' "$work/out" >&2
	else
		echo "ok   $name"
	fi
}

valid='generated\tinternal/adapters/graphql/generated.go\tgqlgen output with a DO NOT EDIT header.\ntest-support\ttests/support\ttest doubles.\n'

make_fixture valid
check "valid exclusions pass" 0 "are valid" "$dir" "$valid"

make_fixture no-reason
check "an entry with an empty reason fails" 1 "has no reason" "$dir" 'generated\tinternal/adapters/graphql/generated.go\t\n'

make_fixture no-reason-field
check "an entry with no reason field fails" 1 "has no reason" "$dir" 'generated\tinternal/adapters/graphql/generated.go\n'

make_fixture blank-reason
check "an entry whose reason is only spaces fails" 1 "has no reason" "$dir" 'generated\tinternal/adapters/graphql/generated.go\t   \n'

make_fixture disallowed-kind
check "a kind other than generated or test-support fails" 1 "is not allowed" "$dir" 'skipped\tinternal/core/domain\tlooks hard to cover.\n'

make_fixture four-fields
check "an entry with four fields fails" 1 "four fields" "$dir" 'generated\tinternal/adapters/graphql/generated.go\treason\textra\n'

make_fixture pattern
check "a path pattern is never an exclusion" 1 "not a plain relative path" "$dir" 'generated\tinternal/adapters/graphql/*.go\tall graphql files.\n'

make_fixture missing-file
check "an excluded file that does not exist fails" 1 "does not exist" "$dir" 'generated\tinternal/adapters/graphql/missing.go\treason.\n'

make_fixture not-go
check "a generated entry that is not a Go file fails" 1 "is not a Go file" "$dir" 'generated\tinternal/adapters/graphql/README.md\treason.\n'

make_fixture no-header
printf 'package graphql\n' >"$dir/internal/adapters/graphql/generated.go"
check "a generated file without the header fails" 1 "no 'Code generated" "$dir" "$valid"

make_fixture header-after-package
printf 'package graphql\n\n// Code generated by gqlgen. DO NOT EDIT.\n' >"$dir/internal/adapters/graphql/generated.go"
check "a header after the package clause does not make a file generated" 1 "no 'Code generated" "$dir" "$valid"

make_fixture wrong-test-support
check "a test-support entry other than tests/support fails" 1 "must be the existing directory tests/support" "$dir" 'test-support\ttests\tall tests.\n'

make_fixture untested-package
mkdir -p "$dir/internal/core/ports"
printf 'package ports\n\ntype Port interface{}\n' >"$dir/internal/core/ports/ports.go"
check "a production package with no test file fails" 1 "have no test file" "$dir" "$valid"

make_fixture missing-exclusion-file
cases=$((cases + 1))
got=0
COVERAGE_ROOT="$dir" COVERAGE_EXCLUSIONS="$work/absent.tsv" sh "$gate" --check-only >"$work/out" 2>&1 || got=$?
if [ "$got" -ne 1 ] || ! grep -F -q -- "is missing" "$work/out"; then
	failed=$((failed + 1))
	echo "FAIL a missing exclusion file fails: got status $got" >&2
else
	echo "ok   a missing exclusion file fails"
fi

if [ "$failed" -ne 0 ]; then
	echo "coverage-gate self-test: $failed of $cases cases failed" >&2
	exit 1
fi
echo "coverage-gate self-test: all $cases cases passed"
